component.schema:
{
 "description": "InferencePoolConfig defines a namespace-scoped pool of inference backends\n(models/upstreams) that can be referenced by AI workloads in the same\nnamespace. The pool is attached to one or more parent resources (e.g. an\nInferenceModelConfig or an Envoy virtual-host) via parentRefs. The Consul\nconnect-inject controller reconciles the pool state and exposes the\nvalidated configuration to Consul; Consul is responsible for the actual\nxDS cluster/route generation.",
 "properties": {
  "spec": {
   "description": "InferencePoolConfigSpec specifies the desired state of the InferencePoolConfig.",
   "properties": {
    "enabled": {
     "default": false,
     "description": "Enabled controls whether this pool is active. When false the controller\nmarks the pool as standing-by and Consul will not advertise the backends.",
     "type": "boolean"
    },
    "parentRefs": {
     "description": "ParentRefs attaches this pool to one or more InferenceGateway resources.\nEach entry must resolve to an InferenceGateway object (to be introduced as\na separate CRD and operator). The InferenceGateway operator discovers all\nInferencePoolConfigs that reference it and composes their rateLimit and\nrouting rules into the gateway's xDS configuration. The controller for\nthis resource validates that every referenced parent exists before marking\nthe pool Ready.",
     "items": {
      "description": "InferencePoolParentRef identifies the InferenceGateway to which this pool\nis attached. When the InferenceGateway CRD and operator are introduced, the\ngateway operator will watch all InferencePoolConfigs whose parentRefs point\nto it and compose their rateLimit and routing rules into the gateway's xDS.",
      "properties": {
       "kind": {
        "description": "Kind is the Kind of the parent resource.\nExpected value once the gateway CRD is available: \"InferenceGateway\".",
        "minLength": 1,
        "type": "string"
       },
       "name": {
        "description": "Name is the name of the parent InferenceGateway resource.",
        "minLength": 1,
        "type": "string"
       },
       "namespace": {
        "description": "Namespace is the namespace of the parent InferenceGateway. When omitted\ndefaults to \"default\". Cross-namespace references require both resources\nto share the same Consul admin partition.",
        "type": "string"
       }
      },
      "required": [
       "kind",
       "name"
      ],
      "type": "object"
     },
     "minItems": 1,
     "type": "array"
    },
    "rateLimit": {
     "description": "RateLimit defines optional token- and request-rate-limiting rules for\nthis pool. When omitted, no rate limiting is applied.",
     "properties": {
      "countMode": {
       "description": "CountMode determines what is counted against limits.\n  total  — count every request regardless of token direction. Default.\n  input  — count only prompt/input tokens.\n  output — count only completion/output tokens.",
       "enum": [
        "total",
        "input",
        "output"
       ],
       "type": "string"
      },
      "default": {
       "description": "Default is the fallback limit pair applied to requests that do not match a more specific tier or model limit.",
       "properties": {
        "requests": {
         "description": "Requests defines the request-count rate limit.",
         "properties": {
          "count": {
           "description": "Count is the maximum allowed number of requests or tokens in the window.",
           "format": "int64",
           "type": "integer"
          },
          "window": {
           "description": "Time unit for the counter window. Must be second, minute, hour, or day.",
           "enum": [
            "second",
            "minute",
            "hour",
            "day"
           ],
           "type": "string"
          }
         },
         "type": "object"
        },
        "tokens": {
         "description": "Tokens defines the token-count rate limit.",
         "properties": {
          "count": {
           "format": "int64",
           "type": "integer"
          },
          "window": {
           "enum": [
            "second",
            "minute",
            "hour",
            "day"
           ],
           "type": "string"
          }
         },
         "type": "object"
        }
       },
       "type": "object"
      },
      "degradeMode": {
       "description": "DegradeMode controls degradation when the rate-limit StateStore is\nunavailable.\n  fail_closed         — reject all requests (HTTP 503). Default.\n  fail_open_unlimited — admit all requests and emit audit log.",
       "enum": [
        "fail_closed",
        "fail_open_unlimited"
       ],
       "type": "string"
      },
      "dimensions": {
       "description": "Dimensions lists request attributes used to partition rate-limit counters (e.g. [\"identity\", \"model\"]).",
       "items": {
        "type": "string"
       },
       "type": "array"
      },
      "enabled": {
       "description": "Enabled controls whether rate limiting is active for this pool.",
       "type": "boolean"
      },
      "enforcement": {
       "description": "Enforcement sets the enforcement mode for rate-limit violations.\n  deny   — requests over limit are rejected (HTTP 429). Default.\n  shadow — limits tracked but never enforced (dry-run).",
       "enum": [
        "deny",
        "shadow"
       ],
       "type": "string"
      },
      "global": {
       "description": "Global is an aggregate limit pair applied across all identities and models for this pool.",
       "properties": {
        "requests": {
         "properties": {
          "count": {
           "format": "int64",
           "type": "integer"
          },
          "window": {
           "enum": [
            "second",
            "minute",
            "hour",
            "day"
           ],
           "type": "string"
          }
         },
         "type": "object"
        },
        "tokens": {
         "properties": {
          "count": {
           "format": "int64",
           "type": "integer"
          },
          "window": {
           "enum": [
            "second",
            "minute",
            "hour",
            "day"
           ],
           "type": "string"
          }
         },
         "type": "object"
        }
       },
       "type": "object"
      },
      "mode": {
       "description": "Mode selects the rate-limit algorithm.\n  soft — V1; per-instance counters with best-effort global sync. Default.\nNote: \"strict\" (V2) is not yet implemented by Consul and is rejected\nwith HTTP 500 at write time. Only \"soft\" is accepted.",
       "enum": [
        "soft"
       ],
       "type": "string"
      },
      "modelLimits": {
       "description": "ModelLimits sets per-model request and token limits.",
       "items": {
        "properties": {
         "model": {
          "description": "Model is the LLM model identifier this limit applies to (e.g. \"gpt-4o\").",
          "type": "string"
         },
         "requests": {
          "properties": {
           "count": {
            "format": "int64",
            "type": "integer"
           },
           "window": {
            "enum": [
             "second",
             "minute",
             "hour",
             "day"
            ],
            "type": "string"
           }
          },
          "type": "object"
         },
         "tokens": {
          "properties": {
           "count": {
            "format": "int64",
            "type": "integer"
           },
           "window": {
            "enum": [
             "second",
             "minute",
             "hour",
             "day"
            ],
            "type": "string"
           }
          },
          "type": "object"
         }
        },
        "type": "object"
       },
       "type": "array"
      },
      "tierBindings": {
       "description": "TierBindings maps SPIFFE identities to rate-limit tiers.",
       "items": {
        "properties": {
         "namespace": {
          "description": "Namespace scopes this binding to a Consul namespace.",
          "type": "string"
         },
         "partition": {
          "description": "Partition scopes this binding to a Consul admin partition.",
          "type": "string"
         },
         "spiffeIDs": {
          "description": "SPIFFEIDs is the list of SPIFFE IDs assigned this tier.",
          "items": {
           "type": "string"
          },
          "type": "array"
         },
         "tier": {
          "description": "Tier is the rate-limit tier name.",
          "type": "string"
         }
        },
        "type": "object"
       },
       "type": "array"
      },
      "tierLimits": {
       "description": "TierLimits sets per-tier request and token limits.",
       "items": {
        "properties": {
         "maxCompletionTokensCap": {
          "description": "MaxCompletionTokensCap caps the max_completion_tokens field for requests from this tier. 0 means no cap.",
          "type": "integer"
         },
         "requests": {
          "properties": {
           "count": {
            "format": "int64",
            "type": "integer"
           },
           "window": {
            "enum": [
             "second",
             "minute",
             "hour",
             "day"
            ],
            "type": "string"
           }
          },
          "type": "object"
         },
         "tier": {
          "description": "Tier is the name of the rate-limit tier.",
          "type": "string"
         },
         "tokens": {
          "properties": {
           "count": {
            "format": "int64",
            "type": "integer"
           },
           "window": {
            "enum": [
             "second",
             "minute",
             "hour",
             "day"
            ],
            "type": "string"
           }
          },
          "type": "object"
         }
        },
        "type": "object"
       },
       "type": "array"
      }
     },
     "type": "object"
    },
    "routing": {
     "description": "Routing defines optional traffic-routing, failover, retry, and caching\nrules for this pool. When omitted, Consul applies its built-in defaults.",
     "properties": {
      "budget": {
       "description": "Budget is an open-ended JSON object for cost/token-budget settings passed to Consul without further validation.",
       "format": "textarea",
       "type": "string"
      },
      "cache": {
       "description": "Cache is an open-ended JSON object for semantic-cache settings passed to Consul without further validation.",
       "format": "textarea",
       "type": "string"
      },
      "complianceMap": {
       "additionalProperties": {
        "properties": {
         "allowedRegions": {
          "description": "AllowedRegions is the list of cloud regions allowed under this compliance regime.",
          "items": {
           "type": "string"
          },
          "type": "array"
         },
         "denyModels": {
          "description": "DenyModels explicitly forbids specific model identifiers under this compliance regime.",
          "items": {
           "type": "string"
          },
          "type": "array"
         }
        },
        "type": "object"
       },
       "description": "ComplianceMap maps a compliance label to its configuration.",
       "type": "object"
      },
      "configValidation": {
       "description": "ConfigValidation sets the strictness of config validation at admission time (e.g. \"strict\", \"warn\", \"off\").",
       "type": "string"
      },
      "fallback": {
       "description": "Fallback tunes cross-provider failover behaviour for capability pools.",
       "properties": {
        "maxTiers": {
         "description": "MaxTiers is the maximum number of provider-level failover hops before the request is failed.",
         "type": "integer"
        },
        "perTryTimeout": {
         "description": "PerTryTimeout is the timeout per failover attempt as a Go duration string (e.g. \"30s\").",
         "type": "string"
        },
        "retryOn": {
         "description": "RetryOn is the list of conditions that trigger a failover attempt to the next provider (e.g. [\"5xx\", \"reset\"]).",
         "items": {
          "type": "string"
         },
         "type": "array"
        }
       },
       "type": "object"
      },
      "fallbackChain": {
       "description": "FallbackChain lists backend names in priority order for cross-provider\nfailover. Deprecated; retained for backward compatibility.",
       "items": {
        "type": "string"
       },
       "type": "array"
      },
      "matchRules": {
       "description": "MatchRules is an ordered list of request-matching rules. The first matching rule wins.",
       "items": {
        "properties": {
         "candidates": {
          "description": "Candidates explicitly lists backend names eligible for matching requests.",
          "items": {
           "type": "string"
          },
          "type": "array"
         },
         "fallbackChain": {
          "description": "FallbackChain lists backend names to try when every candidate is unavailable.",
          "items": {
           "type": "string"
          },
          "type": "array"
         },
         "requireCapabilities": {
          "description": "RequireCapabilities filters candidates to only those advertising all listed capability labels.",
          "items": {
           "type": "string"
          },
          "type": "array"
         },
         "when": {
          "description": "When defines the predicate for this rule.",
          "properties": {
           "bodyHas": {
            "description": "BodyHas is a list of JSON pointer expressions that must be present in the request body.",
            "items": {
             "type": "string"
            },
            "type": "array"
           },
           "identity": {
            "description": "Identity matches requests based on the caller's SPIFFE identity.",
            "properties": {
             "namespace": {
              "type": "string"
             },
             "partition": {
              "type": "string"
             },
             "service": {
              "type": "string"
             }
            },
            "type": "object"
           },
           "path": {
            "description": "Path matches requests whose URL path has this prefix or exact value.",
            "type": "string"
           }
          },
          "type": "object"
         }
        },
        "type": "object"
       },
       "type": "array"
      },
      "mirror": {
       "description": "Mirror is an open-ended JSON object for traffic-mirroring settings passed to Consul without further validation.",
       "format": "textarea",
       "type": "string"
      },
      "retry": {
       "description": "Retry configures automatic retry behaviour for upstream requests.",
       "properties": {
        "maxAttempts": {
         "description": "MaxAttempts is the maximum number of retry attempts per request.",
         "type": "integer"
        },
        "retryOn": {
         "description": "RetryOn is the list of conditions that trigger a retry attempt (e.g. [\"5xx\", \"reset\", \"connect-failure\"]).",
         "items": {
          "type": "string"
         },
         "type": "array"
        }
       },
       "type": "object"
      },
      "scoring": {
       "description": "Scoring tunes the backend-selection scoring model used by Consul when choosing between candidates.",
       "properties": {
        "scorers": {
         "description": "Scorers is the ordered list of scoring strategies to apply (e.g. [\"latency-aware\", \"round-robin\"]).",
         "items": {
          "type": "string"
         },
         "type": "array"
        },
        "weightedSplit": {
         "description": "WeightedSplit defines an explicit weighted split across backend clusters.",
         "items": {
          "description": "InferencePoolWeightedTarget declares a backend cluster and its relative traffic weight.",
          "properties": {
           "cluster": {
            "description": "Cluster is the Consul upstream service name for this target.",
            "type": "string"
           },
           "weight": {
            "description": "Weight is the relative traffic weight assigned to this cluster.",
            "type": "integer"
           }
          },
          "required": [
           "cluster",
           "weight"
          ],
          "type": "object"
         },
         "type": "array"
        }
       },
       "type": "object"
      },
      "timeout": {
       "description": "Timeout configures connection and request timeouts for pool traffic.",
       "properties": {
        "connect": {
         "description": "Connect is the timeout for establishing a connection to the upstream as a Go duration string (e.g. \"5s\").",
         "type": "string"
        },
        "request": {
         "description": "Request is the end-to-end request/response cycle timeout as a Go duration string (e.g. \"120s\").",
         "type": "string"
        }
       },
       "type": "object"
      }
     },
     "type": "object"
    },
    "stateStore": {
     "description": "StateStore locates the shared rate-limit counter as a Consul mesh service.\nRequired when rateLimit.enabled=true — Consul rejects the config entry with\nHTTP 500 if rateLimit is enabled but no StateStore is provided.",
     "properties": {
      "localBindPort": {
       "description": "LocalBindPort is the loopback port that the gateway's Envoy binds and that\nthe rate-limit processor dials to reach the counter store (1-65535).",
       "maximum": 65535,
       "minimum": 1,
       "type": "integer"
      },
      "service": {
       "description": "Service is the Consul mesh service name of the rate-limit counter store\n(e.g. \"valkey\", \"redis\"). Must be registered in the Consul catalog and\nreachable via service-mesh mTLS from the gateway.",
       "minLength": 1,
       "type": "string"
      }
     },
     "required": [
      "service",
      "localBindPort"
     ],
     "type": "object"
    }
   },
   "required": [
    "enabled",
    "parentRefs"
   ],
   "type": "object"
  }
 },
 "title": "Inference Pool Config",
 "type": "object"
}
